import{_ as t,o as d,c as o,a0 as c}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"Event envelope","description":"","frontmatter":{},"headers":[],"relativePath":"reference/event-envelope.md","filePath":"reference/event-envelope.md"}'),r={name:"reference/event-envelope.md"};function n(a,e,i,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="event-envelope" tabindex="-1">Event envelope <a class="header-anchor" href="#event-envelope" aria-label="Permalink to &quot;Event envelope&quot;">​</a></h1><p>Every unit the bus carries, nodes react to, and the log records is a flat JSON object — the <code>Event</code> in <code>peregrin-core</code>. This is a P0 contract: later substrate work (ingress drivers, durable stores, remote transport) builds against exactly this shape.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td>Routing key — dot-separated segments (<code>lint.passed</code>). Serialized as <code>type</code>; <code>kind</code> is accepted as an alias on decode.</td></tr><tr><td><code>payload</code></td><td>any JSON</td><td>Event data, opaque to the bus. Defaults to <code>{}</code> when absent. Validated per type by <code>events:</code>/<code>payload_schemas:</code> and driver <code>output</code> contracts.</td></tr><tr><td><code>source</code></td><td>string</td><td>Emitting node id, or <code>__runner__</code> for engine-synthetic events. Replay (<code>seed</code>) counts prior fires per <code>source</code>; runner-sourced events don&#39;t count.</td></tr><tr><td><code>id</code></td><td>string</td><td><code>uuid v4</code> truncated to 12 chars. Observational only — defaulted on decode, never a routing input.</td></tr><tr><td><code>ts</code></td><td>integer</td><td>Emission time, epoch milliseconds. Observational; defaulted on decode.</td></tr></tbody></table><p>Rules:</p><ul><li><strong>The envelope is closed.</strong> These five fields are the entire shape. Run-scoped routing data rides in <code>payload</code>, never at top level — there is no <code>state_key</code> field (v1 never had one either; scoped state keys are produced from <code>node.state.key</code> and surface inside payloads, e.g. <code>node.skipped</code>&#39;s <code>{node, state_key}</code>).</li><li><strong>CI/git metadata</strong> (<code>repo</code>, <code>ref</code>, <code>sha</code>, <code>clone_url</code>, <code>actor</code>) goes inside <code>payload</code> — conventionally under a reserved <code>origin</code> block when a pipeline wants a standard slot. Never new top-level fields.</li><li><strong>Nothing secret, ever.</strong> Secrets reach nodes through the run&#39;s secrets record (<code>ctx.secrets</code>), the <code>capabilities.secrets</code> allow-list, and <code>${secret.*}</code> template resolution — see <a href="./scope-resolution.html">Scope resolution</a>. The envelope carries no secret material so event logs stay shareable.</li></ul><h2 id="engine-synthetic-events" tabindex="-1">Engine-synthetic events <a class="header-anchor" href="#engine-synthetic-events" aria-label="Permalink to &quot;Engine-synthetic events&quot;">​</a></h2><p>Emitted with <code>source: &quot;__runner__&quot;</code> (or the affected node id for <code>node.*</code> types). Synthetic types are exempt from payload-schema validation.</p><table tabindex="0"><thead><tr><th>Type</th><th>When</th><th>Payload</th></tr></thead><tbody><tr><td><code>start</code></td><td>Run begins (when no <code>replay_events</code> are seeded)</td><td><code>{}</code></td></tr><tr><td><code>workflow.done</code></td><td>Pending and ready queues drained cleanly</td><td><code>{}</code></td></tr><tr><td><code>workflow.cancel</code></td><td>A cancellation request event</td><td><code>{reason}</code></td></tr><tr><td><code>workflow.cancelled</code></td><td>Run ended via cancel or <code>stop_on</code></td><td><code>{reason}</code></td></tr><tr><td><code>workflow.failed</code></td><td>A node failure marked the run failed</td><td><code>{node, error}</code></td></tr><tr><td><code>workflow.cycle_detected</code></td><td>Cycle detection tripped (observer <code>cycle</code> flag)</td><td>—</td></tr><tr><td><code>node.failed</code></td><td>Driver error, validation failure, capability violation, retry exhausted</td><td><code>{error, node}</code></td></tr><tr><td><code>node.exhausted</code></td><td><code>max_fires</code> cap reached (once per node)</td><td><code>{node, maxFires}</code></td></tr><tr><td><code>node.skipped</code></td><td><code>state.skip_if</code> evaluated truthy</td><td><code>{node, state_key}</code></td></tr><tr><td><code>event.invalid</code></td><td>Payload failed schema validation</td><td><code>{eventType, errors, payload}</code></td></tr><tr><td><code>capability.violation</code></td><td>Merged capability policy denied the fire</td><td><code>{node, violations}</code></td></tr><tr><td><code>circuit.open</code></td><td>Breaker tripped (type is <code>circuit_breaker.on_trip</code>-configurable)</td><td><code>{node, failures}</code></td></tr><tr><td><code>&lt;node-id&gt;.tick</code></td><td>Poll-node self-trigger (auto-declared in <code>on</code>/<code>emits</code>)</td><td><code>{poll: true}</code></td></tr><tr><td><code>&lt;node-id&gt;.fire</code></td><td><code>schedule</code> self-retrigger — arms the next cron occurrence (auto-declared in <code>on</code>/<code>emits</code>)</td><td><code>{schedule: true}</code></td></tr><tr><td><code>&lt;node-id&gt;.scheduled</code></td><td><code>schedule</code> armed a deferred emission (auto-declared in <code>emits</code>)</td><td><code>{cron, timezone, next_fire}</code></td></tr><tr><td><code>&lt;node-id&gt;.delayed</code></td><td><code>delay</code> armed a deferred emission (<strong>not</strong> auto-declared — strict campaigns list it in <code>emits</code>)</td><td><code>{duration, duration_ms, until}</code></td></tr></tbody></table><h2 id="emission-contract-—-three-layers" tabindex="-1">Emission contract — three layers <a class="header-anchor" href="#emission-contract-—-three-layers" aria-label="Permalink to &quot;Emission contract — three layers&quot;">​</a></h2><p>Events reach the graph through three distinct mechanisms; only the first is engine-checked.</p><p><strong>1. <code>emits:</code> declaration (engine).</strong> The node&#39;s advertised output types. Under <code>strict: true</code>, preflight requires every node to declare non-empty <code>on:</code> and <code>emits:</code>, and at fire time <strong>every event a node produces must literally appear in <code>emits</code></strong> — the check is exact match, not glob. Exempt engine types: <code>node.failed</code>, <code>circuit.open</code>, <code>node.skipped</code> (and <code>event.invalid</code>, which is produced at publish time, not fire time). Poll nodes get <code>&lt;id&gt;.tick</code> auto-appended to <code>emits</code> at load; <code>schedule</code> nodes get <code>&lt;id&gt;.fire</code> + <code>&lt;id&gt;.scheduled</code>.</p><blockquote><p>Open question — <strong>I-012</strong>: exact-match <code>emits</code> makes wildcard/shard emit types undeclarable under strict (a node emitting <code>shard.42.done</code> cannot satisfy <code>emits: [shard.*.done]</code>). Glob-match <code>emits</code> is the likely ruling for map/shard patterns; until decided, strict campaigns with dynamic emit types must enumerate them.</p></blockquote><p><strong>2. <code>params.emit</code> (driver convention).</strong> A per-driver map of return code → event type: <code>emit[&quot;&lt;rc&gt;&quot;]</code> first, then the <code>emit.default</code> arm. <code>driver: shell</code> uses it to turn <code>rc</code> into domain events (<code>cmd.done</code> on <code>rc == 0</code>, <code>node.failed</code> otherwise). The engine never interprets <code>params.emit</code> — it is an ordinary resolved param.</p><p><strong>3. <code>ctx.emit()</code> + <code>forward:</code> (side channels).</strong> A driver may push extra events onto the run&#39;s pending queue via <code>ctx.emit</code>; they are published after that node&#39;s own returned events. Separately, <code>forward:</code> re-emits each trigger event: for every trigger × every <code>forward</code> pattern, a new event is produced with the trigger&#39;s payload and <code>source</code> = this node. <code>*</code>/<code>**</code> segments inside the forward pattern are replaced by the wildcard captures (<code>match.1</code>, <code>match.2</code>, …) of the first <code>on</code> pattern that matched the trigger; a capture slot with no match stays literal <code>*</code>.</p><p>Two more driver side channels shape the graph: <code>ctx.inject(specs)</code> adds nodes mid-run (the <code>runner</code> driver reads them from the trigger&#39;s <code>payload.nodes</code> / <code>payload.workflow.nodes</code>), and <code>ctx.request_shutdown()</code> cancels the run after the current batch.</p><p>Outside the driver model, the <strong>ingress injection channel</strong> (<code>peregrin_engine::ingress()</code>) lets external producers — webhook listeners, WAL pollers, the supersede queue&#39;s cancel signal — push <code>Event</code>s into a live run without <code>&amp;mut</code> access to the bus: the <code>Injector</code> half is <code>Send + Sync</code> and cloneable, the runner drains the <code>Ingress</code> half into <code>pending</code> once per loop iteration, so injected events serialize after everything already pending. See <a href="./queue-supersede.html">Queue &amp; supersede</a>.</p>',17)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
